import openpyxl
wb = openpyxl.load_workbook('documents/renovation-budget-draw-schedule.xlsx', data_only=True)
ws = wb['Draw Schedule']
rows=list(ws.iter_rows(values_only=True))
hdr=rows[0]
def num(v):
    if v is None: return 0.0
    if isinstance(v,(int,float)): return float(v)
    return float(str(v).replace('$','').replace(',',''))
idx={}
for i,h in enumerate(hdr):
    if h: idx.setdefault(str(h),i)
li=[i for i,h in enumerate(hdr) if h and 'Total Lender Draw' in str(h)][0]
bi=[i for i,h in enumerate(hdr) if h and 'Total Borrower Equity This Month' in str(h)][0]
cL=[i for i,h in enumerate(hdr) if h and 'Cumulative Lender' in str(h)][0]
cB=[i for i,h in enumerate(hdr) if h and 'Cumulative Borrower' in str(h)][0]
cT=[i for i,h in enumerate(hdr) if h and 'Cumulative Total' in str(h)][0]
L=B=0
for r in rows[1:15]:
    if r[0] is None: continue
    L+=num(r[li]); B+=num(r[bi])
print("sum lender draws {:,.2f}  borrower {:,.2f}  total {:,.2f}".format(L,B,L+B))
print("final cum lender {:,.2f} borrower {:,.2f} total {:,.2f}".format(num(rows[14][cL]),num(rows[14][cB]),num(rows[14][cT])))
# month-by-month cumulative check
cl=cb=0
for r in rows[1:15]:
    if r[0] is None: continue
    cl+=num(r[li]); cb+=num(r[bi])
    if abs(cl-num(r[cL]))>0.5 or abs(cb-num(r[cB]))>0.5:
        print("mismatch month", r[0], "computed", cl, cb, "stated", num(r[cL]), num(r[cB]))
print("overrun vs budget: lender {:,.0f} borrower {:,.0f}".format(L-2250000, B-900000))
EOF"}

